const SelectGrid& EmbeddedSelectGrid()
{
	static const SelectGrid grid = [] {
		SelectGrid parsed;
		std::string error;
		if (!ParseSelectGrid(kEmbeddedSelectGridJson, parsed, error)) parsed = {};
		return parsed;
	}();
	return grid;
}

